urgency:(t)=>{if(typeof t!=='string')return{score:0,factor:0,urgentWords:0,totalWords:0};const u=new Set(['urgent','asap','immediately','now','quick','quickly','hurry','hurryup','emergency','critical','important','priority','deadline','soon','soonest','expedite','rush','instant','prompt','promptly','rightaway','stat','fast','faster','fastest','rapid','rapidly','sudden','suddenly','immediate','pressing','vital','crucial','essential','mandatory','required','imperative','necessity','top priority','high priority','time sensitive','no time','running out','last minute','eleventh hour','breaking','live','active','ongoing','developing','unfolding','serious','grave','severe','drastic','desperate','desperately','emergency','crisis','911','sos','help','alert','warning','caution','danger','dangerous','threat','threaten','alarm','panic','panicking','frantic','frantically','hysterical','hysterically','chaotic','chaos','turmoil','turbulent','disaster','catastrophe','catastrophic','calamity','meltdown','collapse','breakdown','crash','crashing','failing','failure','fatal','deadly','lethal','critical','code red','red alert','mayday','distress','life or death','life-threatening','now or never','do or die','no time to waste','time is running','urgency','urgent care','fast track','expedited','rush order','speed up','accelerate','hasten','hurry','rush','scramble','dash','race','sprint','bolt','flee','escape','evacuate','evacuation','rescue','save','survival','survive','crisis management','damage control','fire drill','emergency response','triage','first aid','lifeline','lifesaving','last chance','final warning','ultimatum','deadline approaching','due soon','overdue','late','delayed','delay','postpone','cancel','cancelled','abort','aborted','halt','halted','stop','stopped','pause','paused','freeze','frozen','standby','hold','holding','on hold','backlog','queued','waitlist']);const l=t.toLowerCase();const words=l.split(/\s+/);let c=0;for(const x of words)u.has(x.replace(/[^a-z]/g,''))&&c++;const exc=(t.match(/!/g)||[]).length;const ques=(t.match(/\?/g)||[]).length;const caps=(t.replace(/[^A-Z]/g,'').length||0);const sents=tokenizers.bySentences(t).length||1;const capsRatio=t.length?caps/t.length:0;const excRatio=sents?exc/sents:0;const wordRatio=words.length?c/words.length:0;const urgencyScore=(wordRatio*2+excRatio*0.3+ques*0.05+(capsRatio>0.4?0.5:0)+(capsRatio>0.6?0.5:0))/3.4;return{score:Math.min(1,urgencyScore),urgentWords:c,totalWords:words.length,wordRatio,exclamations:exc,questions:ques,capsRatio,factor:Math.tanh(urgencyScore*3)}},
