ambiguity:(t)=>{if(typeof t!=='string')return{score:0,count:0,total:0,level:'none'};const w=tokenizers.byWords(t,true);const amb=new Set(['it','that','this','those','these','they','them','he','she','his','her','their','its','there','then','here','something','someone','somebody','somewhere','sometime','somehow','somewhat','thing','stuff','what','which','who','whom','whose','whatever','whoever','whichever','wherever','whenever','however','anything','anyone','anybody','anywhere','anytime','anyway','anyhow','everything','everyone','everybody','everywhere','always','never','sometimes','often','usually','rarely','seldom','occasionally','frequently','generally','typically','normally','commonly','regularly','periodically','many','much','several','numerous','countless','various','diverse','multiple','plenty','lots','tons','heaps','loads','masses','abundance','plethora','myriad','multitude','variety','range','array','assortment','selection','mixture','combination','set','group','bunch','cluster','batch','some','any','all','each','every','both','few','most','none','no one','nobody','nothing','nowhere','neither','either']);let c=0;for(const x of w)amb.has(x)&&c++;const ratio=w.length?c/w.length:0;return{score:ratio,count:c,total:w.length,level:ratio>0.5?'high':ratio>0.3?'moderate':'low'}},
complexity:(t)=>{if(typeof t!=='string')return{words:0,sentences:1,readability:0,density:0};const w=tokenizers.byWords(t,false).length||1;const s=tokenizers.bySentences(t).length||1;const syCnt=[...t.toLowerCase().matchAll(/[aeiou]+/g)].length||1;const wordLens=tokenizers.byWords(t,false).map(x=>x.length);const avgWL=wordLens.reduce((a,b)=>a+b,0)/w;const avgSL=w/s;const avgSyW=syCnt/w;const flesch=206.835-1.015*(w/s)-84.6*(syCnt/w);const unique=new Set(tokenizers.byWords(t,true).map(x=>x.replace(/[^a-z]/g,''))).size;return{words:w,sentences:s,syllables:syCnt,avgWordLen:avgWL,avgSentenceLen:avgSL,avgSyllablesPerWord:avgSyW,readability:flesch,density:unique/w}},
coherence:(t)=>{const st=tokenizers.bySentences(t);if(st.length<2)return{score:1,coherent:true};let sim=0,c=0;for(let i=1;i<st.length;i++){const a=vectors.create(st[i-1]),b=vectors.create(st[i]);if(Object.keys(a).length&&Object.keys(b).length){sim+=vectors.cosine(a,b);c++}}const avg=sim/Math.max(1,c);return{score:avg,coherent:avg>0.15,transitions:c}},
