cluster:(items)=>{if(!items||!items.length)return[];const vecs=items.map(item=>({item,vector:vectors.create(typeof item==='string'?item:item.text||'')}));const sims=[];for(let i=0;i<vecs.length;i++)for(let j=i+1;j<vecs.length;j++)sims.push({i,j,sim:vectors.cosine(vecs[i].vector,vecs[j].vector)});sims.sort((a,b)=>b.sim-a.sim);const threshold=0.3;const groups=[];const asgn=new Set();for(const{i,j,sim}of sims){if(sim<threshold)break;if(!asgn.has(i)&&!asgn.has(j)){const g=[i,j];let added=true;while(added){added=false;for(let k=0;k<vecs.length;k++)if(!asgn.has(k)&&!g.includes(k)){let avg=0,c=0;for(const m of g){avg+=vectors.cosine(vecs[k].vector,vecs[m].vector);c++}if(c&&avg/c>threshold){g.push(k);added=true}}}asgn.add(i);asgn.add(j);groups.push(g.map(idx=>vecs[idx]))}}for(let i=0;i<vecs.length;i++)if(!asgn.has(i))groups.push([vecs[i]]);return groups},
