outliers:(texts)=>{if(!texts||texts.length<3)return[];const vecs=texts.map(t=>vectors.create(t));const avg={};let cnt=0;for(const v of vecs){for(const k in v)avg[k]=(avg[k]||0)+v[k];cnt++}for(const k in avg)avg[k]/=cnt;const scored=texts.map((t,i)=>{const d=vectors.euclidean(vecs[i],avg);return{text:t,index:i,deviation:d}});scored.sort((a,b)=>b.deviation-a.deviation);const meanDev=scored.reduce((a,b)=>a+b.deviation,0)/scored.length;const stdDev=Math.sqrt(scored.reduce((a,b)=>a+(b.deviation-meanDev)**2,0)/scored.length);return scored.filter(s=>s.deviation>meanDev+stdDev*1.5).map(s=>({text:s.text,index:s.index,deviation:s.deviation,zScore:(s.deviation-meanDev)/(stdDev||1)}))},
