distance:(a,b,metric='cosine')=>{const av=vectors.create(a),bv=vectors.create(b);const m={cosine:()=>1-vectors.cosine(av,bv),euclidean:()=>vectors.euclidean(av,bv),manhattan:()=>vectors.manhattan(av,bv),jaccard:()=>1-vectors.jaccard(av,bv),dice:()=>1-vectors.dice(av,bv),overlap:()=>1-vectors.overlap(av,bv),braycurtis:()=>vectors.braycurtis(av,bv),canberra:()=>vectors.canberra(av,bv),chebyshev:()=>vectors.chebyshev(av,bv)};return(m[metric]||m.cosine)()}
