train:(examples)=>{let added=0;for(const ex of examples){const id=ex.input?.substring(0,50)+':'+ex.label;if(!learner.memory[id]){learner.memory[id]=true;learner.corpus[ex.label]||(learner.corpus[ex.label]=[]);learner.corpus[ex.label].push({text:ex.input||'',label:ex.label,sentiment:extractors.sentiment(ex.input||'').score,subjectivity:extractors.subjectivity(ex.input||'').score,formality:extractors.formality(ex.input||'').index,intent:extractors.intent(ex.input||'').type,complexity:extractors.complexity(ex.input||'').words,vector:vectors.create(ex.input||'')});safetyAnalyzers.learn(ex.input,ex.label);added++}}return added},
classify:(input)=>{const nb=classifiers.naiveBayes(input,learner.corpus.innocent?.map(c=>c.text)||[],learner.corpus.dangerous?.map(c=>c.text)||[]);const allCorpus=[...(learner.corpus.innocent||[]).map(c=>({...c,label:'innocent'})),...(learner.corpus.dangerous||[]).map(c=>({...c,label:'dangerous'}))];const knn=allCorpus.length>=5?classifiers.knn(input,allCorpus,5):null;const svm=allCorpus.length?classifiers.svm(input,allCorpus):null;const ctx=safetyAnalyzers.evaluate(input,'');const votes=[nb.verdict?1:0,knn?.verdict==='innocent'?1:knn?.verdict==='dangerous'?0:0.5,svm?.verdict==='innocent'?1:svm?.verdict==='dangerous'?0:0.5];const es=votes.reduce((a,b)=>a+b,0)/votes.length;const ev=es>0.5?'innocent':'dangerous';const ec=Math.abs(es-0.5)*2;return{classifier:{naiveBayes:nb,knn:knn,svm:svm,ensemble:{verdict:ev,confidence:ec,score:es}},context:safetyAnalyzers.judge(ctx.allRisks||[]),combined:{verdict:ev==='innocent'&&!ctx.verdict?.flag?'innocent':'dangerous',confidence:(ec+(ctx.verdict?.confidence||0))/2}}},
