stats:()=>{const c=[...(learner.corpus.innocent||[]),...(learner.corpus.dangerous||[])];return{corpusSize:c.length,distribution:{innocent:learner.corpus.innocent?.length||0,dangerous:learner.corpus.dangerous?.length||0},avgSentiment:c.length?c.reduce((a,b)=>a+b.sentiment,0)/c.length:0,memorySize:Object.keys(learner.memory).length}},
analyzeChat:(messages)=>{if(!messages||!messages.length)return[];const analyses=[];for(let i=0;i<messages.length;i++){const msg=messages[i];if(msg.role==='user'){const next=i+1<messages.length?messages[i+1]:null;const a=safetyAnalyzers.evaluate(msg.text||'',next?.text||'');analyses.push({index:i,input:msg.text,output:next?.text||'',verdict:a.verdict,risks:a.allRisks})}}return analyses}
